-- Date-based reminders are not workflow approvals. Existing233 facts stay intact.
CREATE TABLE ty_br_lease(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),house_id bigint NOT NULL REFERENCES ty_dorm_house(id),
 source_key text NOT NULL,version integer NOT NULL CHECK(version>0),starts_on date NOT NULL,ends_on date NOT NULL,evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','verified','rejected','withdrawn')),created_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),reviewed_at timestamptz,review_ref text,withdrawn_by bigint REFERENCES sys_account(id),withdrawn_at timestamptz,withdraw_reason text,
 revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(ends_on>=starts_on),CHECK(status NOT IN('verified','rejected','withdrawn')OR(reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),CHECK(status<>'withdrawn'OR(withdrawn_by IS NOT NULL AND withdrawn_at IS NOT NULL AND length(btrim(withdraw_reason))>=4)),UNIQUE(group_id,house_id,source_key,version)
);
CREATE TABLE ty_br_rule(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),profile_id bigint REFERENCES ty_ix_profile(id),profile_revision integer,
 code text NOT NULL,name text NOT NULL,version integer NOT NULL CHECK(version>0),reminder_types text[] NOT NULL,lead_days integer NOT NULL CHECK(lead_days BETWEEN 0 AND 730),overdue_days integer NOT NULL DEFAULT 0 CHECK(overdue_days BETWEEN 0 AND 730),
 schedule text NOT NULL CHECK(schedule IN('daily','threshold_days')),threshold_days integer[] NOT NULL DEFAULT '{}',timezone text NOT NULL,recipient_strategy text NOT NULL CHECK(recipient_strategy IN('explicit','subject','explicit_and_subject')),recipient_account_ids bigint[] NOT NULL DEFAULT '{}',
 origin text NOT NULL,evidence_ref text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,last_scanned_at timestamptz,last_scan_error text,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(cardinality(reminder_types)>0 AND reminder_types<@ARRAY['contract_expiry','certificate_expiry','dorm_stay_expiry','dorm_lease_expiry']::text[]),CHECK((profile_id IS NULL)=(profile_revision IS NULL)),CHECK(schedule<>'threshold_days'OR cardinality(threshold_days)>0),
 CHECK(status<>'approved'OR(profile_id IS NOT NULL AND approved_by IS NOT NULL AND approved_at IS NOT NULL)),UNIQUE(group_id,code,version)
);
CREATE TABLE ty_br_notice(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),kind text NOT NULL CHECK(kind IN('contract_expiry','certificate_expiry','dorm_stay_expiry','dorm_lease_expiry')),
 source_id bigint NOT NULL,source_key text NOT NULL,source_revision text NOT NULL,source_hash text NOT NULL,due_on date NOT NULL,date_semantics text NOT NULL,timezone text NOT NULL,
 subject_person_id bigint REFERENCES ty_person(id),recipient_account_id bigint NOT NULL REFERENCES sys_account(id),recipient_person_id bigint NOT NULL REFERENCES ty_person(id),
 state text NOT NULL DEFAULT'open'CHECK(state IN('open','superseded','resolved','blocked')),reason_code text,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),closed_at timestamptz,
 UNIQUE(group_id,kind,source_key,source_hash,recipient_account_id)
);
CREATE TABLE ty_br_delivery(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_key text NOT NULL UNIQUE CHECK(public_key~'^[a-f0-9]{32}$'),rule_id bigint NOT NULL REFERENCES ty_br_rule(id),rule_code text NOT NULL,notice_id bigint NOT NULL REFERENCES ty_br_notice(id),
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),cycle_key text NOT NULL,
 source_key text NOT NULL,source_hash text NOT NULL,due_on date NOT NULL,recipient_account_id bigint NOT NULL REFERENCES sys_account(id),recipient_person_id bigint NOT NULL REFERENCES ty_person(id),
 identity_id bigint REFERENCES ty_ix_identity(id),identity_revision integer,recipient_external_id text,job_id bigint UNIQUE REFERENCES ty_ix_job(id),transport_receipt_id bigint REFERENCES ty_ix_delivery_receipt(id),
 state text NOT NULL DEFAULT'pending'CHECK(state IN('pending','queued','blocked','closed')),acceptance_state text NOT NULL DEFAULT'not_reported'CHECK(acceptance_state IN('not_reported','provider_accepted','failed','unknown')),delivery_state text NOT NULL DEFAULT'not_reported'CHECK(delivery_state IN('not_reported','implied_by_read')),read_state text NOT NULL DEFAULT'not_reported'CHECK(read_state IN('not_reported','provider_reported_read','provider_reported_unread')),
 platform_result text,remote_id text,reported_read_at timestamptz,observed_read_at timestamptz,last_polled_at timestamptz,error_code text,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(num_nonnulls(identity_id,identity_revision,recipient_external_id)IN(0,3)),UNIQUE(group_id,rule_code,connection_id,source_key,due_on,recipient_person_id,cycle_key)
);
CREATE TABLE ty_br_receipt_job(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,delivery_id bigint NOT NULL REFERENCES ty_br_delivery(id),requested_by bigint NOT NULL REFERENCES sys_account(id),state text NOT NULL DEFAULT'queued'CHECK(state IN('queued','leased','completed','failed','blocked')),
 lease_token text,lease_until timestamptz,attempts integer NOT NULL DEFAULT 0,error_code text,result jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,CHECK((state='leased')=(lease_token IS NOT NULL AND lease_until IS NOT NULL))
);
CREATE UNIQUE INDEX ty_br_one_receipt_lease ON ty_br_receipt_job(delivery_id)WHERE state IN('queued','leased');
CREATE TABLE ty_br_observation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),delivery_id bigint REFERENCES ty_br_delivery(id),envelope_id bigint REFERENCES ty_ix_callback_envelope(id),receipt_job_id bigint REFERENCES ty_br_receipt_job(id),
 source_key text NOT NULL,proof_kind text NOT NULL CHECK(proof_kind IN('verified_callback','authenticated_query')),provider text NOT NULL CHECK(provider IN('feishu','dingtalk')),remote_id text NOT NULL,recipient_external_id text NOT NULL,
 kind text NOT NULL CHECK(kind IN('read','unread','failed','invalid_recipient','not_reported')),reported_at timestamptz,payload_hash text NOT NULL,payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,
 state text NOT NULL DEFAULT'unmatched'CHECK(state IN('unmatched','applied','blocked')),error_code text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),applied_at timestamptz,last_checked_at timestamptz,
 UNIQUE(connection_id,source_key),CHECK((proof_kind='verified_callback')=(envelope_id IS NOT NULL)),CHECK((proof_kind='authenticated_query')=(receipt_job_id IS NOT NULL))
);
-- Scope, provenance and receipt-proof guards are appended after service ABI review.
ALTER TABLE ty_br_notice ADD CHECK(source_hash~'^[a-f0-9]{64}$');
ALTER TABLE ty_br_delivery ADD CHECK(source_hash~'^[a-f0-9]{64}$');
CREATE FUNCTION fn_ty_br_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_br_rule%ROWTYPE;n public.ty_br_notice%ROWTYPE;d public.ty_br_delivery%ROWTYPE;c public.ty_integration_connection%ROWTYPE;p public.ty_ix_profile%ROWTYPE;j public.ty_ix_job%ROWTYPE;m public.ty_ix_identity%ROWTYPE;g bigint;co bigint;person bigint;due date;rev text;source_status text;actor_person bigint;actor_group bigint;mutable text[];v integer;account_key bigint;basis_key text;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 到期依据、通知与回执历史保留';END IF;
 IF TG_TABLE_NAME='ty_br_lease'THEN
  SELECT h.group_id,h.company_id INTO g,co FROM public.ty_dorm_house h WHERE h.id=NEW.house_id;
  IF g IS DISTINCT FROM NEW.group_id OR co IS DISTINCT FROM NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 租约截止日期须对应同集团公司的实际房源';END IF;
  mutable:=ARRAY['status','reviewed_by','reviewed_at','review_ref','withdrawn_by','withdrawn_at','withdraw_reason','revision'];
  IF TG_OP='INSERT'AND(NEW.status<>'draft'OR NEW.reviewed_by IS NOT NULL OR NEW.withdrawn_by IS NOT NULL)OR TG_OP='UPDATE'AND((to_jsonb(NEW)-mutable)IS DISTINCT FROM(to_jsonb(OLD)-mutable)OR NEW.revision<>OLD.revision+1 OR NOT(OLD.status='draft'AND NEW.status IN('verified','rejected')OR OLD.status='verified'AND NEW.status='withdrawn')OR OLD.reviewed_by IS NOT NULL AND ROW(NEW.reviewed_by,NEW.reviewed_at,NEW.review_ref)IS DISTINCT FROM ROW(OLD.reviewed_by,OLD.reviewed_at,OLD.review_ref))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 租约日期原依据只建新版本，核定与停止留独立凭据';END IF;
  IF NEW.status IN('verified','rejected','withdrawn')AND public.fn_ty_pr_same_actor(NEW.created_by,NEW.reviewed_by)OR NEW.status='withdrawn'AND public.fn_ty_pr_same_actor(NEW.created_by,NEW.withdrawn_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 租约日期须由另一自然人独立核定或停止';END IF;
 ELSIF TG_TABLE_NAME='ty_br_rule'THEN
  SELECT*INTO c FROM public.ty_integration_connection WHERE id=NEW.connection_id;SELECT*INTO p FROM public.ty_ix_profile WHERE id=NEW.profile_id;
  IF c.group_id IS DISTINCT FROM NEW.group_id OR c.provider NOT IN('dingtalk','feishu','wecom')OR NEW.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company x WHERE x.id=NEW.company_id AND x.group_id=NEW.group_id)OR c.company_id IS NOT NULL AND(NEW.company_id IS NULL OR NOT public.fn_ty_ix_company_contains(c.company_id,NEW.company_id))OR NEW.profile_id IS NOT NULL AND(p.id IS NULL OR p.connection_id<>c.id OR p.company_id IS NOT NULL AND(NEW.company_id IS NULL OR NOT public.fn_ty_ix_company_contains(p.company_id,NEW.company_id)))OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=NEW.timezone)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 日期提醒须明确同集团公司连接、内部应用及有效时区';END IF;
  FOREACH v IN ARRAY NEW.threshold_days LOOP IF v< -NEW.overdue_days OR v>NEW.lead_days THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 提醒阈值日在配置窗口之外';END IF;END LOOP;
  -- Current references are required on creation/authorization. A later revocation
  -- must still allow recording a blocked scan or disabling the historic rule.
  IF TG_OP='INSERT'OR NEW.status='approved'AND OLD.status IS DISTINCT FROM NEW.status THEN
  FOREACH account_key IN ARRAY NEW.recipient_account_ids LOOP
   SELECT CASE WHEN b.account_id IS NOT NULL THEN b.group_id ELSE f.group_id END,CASE WHEN b.account_id IS NOT NULL THEN b.person_id ELSE f.person_id END INTO actor_group,actor_person FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile f ON f.account_id=a.id WHERE a.id=account_key AND a.status='active';
   IF actor_group IS DISTINCT FROM NEW.group_id OR actor_person IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 收件账号须明确绑定同集团当前人员';END IF;
  END LOOP;
  END IF;
  mutable:=ARRAY['status','approved_by','approved_at','revision','last_scanned_at','last_scan_error'];
  IF TG_OP='UPDATE'AND((to_jsonb(NEW)-mutable)IS DISTINCT FROM(to_jsonb(OLD)-mutable)OR NEW.revision<>OLD.revision AND NEW.revision<>OLD.revision+1 OR OLD.approved_by IS NOT NULL AND ROW(NEW.approved_by,NEW.approved_at)IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)OR NEW.status IS DISTINCT FROM OLD.status AND NOT(OLD.status='draft'AND NEW.status IN('approved','disabled')OR OLD.status='approved'AND NEW.status='disabled')OR NEW.status IS DISTINCT FROM OLD.status AND NEW.revision<>OLD.revision+1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已核日期发送规则只建新版本，不换授权人或复活';END IF;
  IF NEW.status='approved'AND(TG_OP='INSERT'OR OLD.status IS DISTINCT FROM NEW.status)AND(p.id IS NULL OR p.status<>'approved'OR p.revision<>NEW.profile_revision OR p.application_type<>'internal'OR NOT'message.send'=ANY(p.enabled_capabilities)OR c.status<>'active'OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 自动提醒须独立HR授权和已核内部应用，不能用待配置草稿发送';END IF;
 ELSIF TG_TABLE_NAME='ty_br_notice'THEN
  IF TG_OP='INSERT'THEN
   IF NEW.kind='contract_expiry'THEN SELECT x.group_id,x.company_id,x.person_id,x.ends_on,x.revision::text,x.status INTO g,co,person,due,rev,source_status FROM public.ty_hr_contract x WHERE x.id=NEW.source_id;IF source_status<>'signed'OR NEW.date_semantics<>'contract_inclusive_end'OR NEW.source_key<>'contract:'||NEW.source_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 合同提醒须引用实际已签合同的截至日';END IF;
   ELSIF NEW.kind='certificate_expiry'THEN SELECT x.group_id,x.company_id,x.person_id,x.valid_to,x.revision::text,x.state,'certificate:'||x.source_key INTO g,co,person,due,rev,source_status,basis_key FROM public.ty_cert_holding x WHERE x.id=NEW.source_id;IF source_status<>'verified'OR NEW.date_semantics<>'certificate_first_invalid'OR NEW.source_key IS DISTINCT FROM basis_key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 证照提醒须引用实际核验证照的失效日';END IF;
   ELSIF NEW.kind='dorm_stay_expiry'THEN SELECT x.group_id,x.company_id,x.person_id,(x.ends_at AT TIME ZONE NEW.timezone)::date,x.revision::text,x.state INTO g,co,person,due,rev,source_status FROM public.ty_dorm_stay x WHERE x.id=NEW.source_id;IF source_status<>'occupied'OR NEW.date_semantics<>'stay_exclusive_end'OR NEW.source_key<>'dorm-stay:'||NEW.source_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 入住提醒须对应实际在住床位及明确结束时间';END IF;
   ELSE SELECT x.group_id,x.company_id,NULL::bigint,x.ends_on,x.revision::text,x.status,'dorm-lease:'||x.house_id||':'||x.source_key INTO g,co,person,due,rev,source_status,basis_key FROM public.ty_br_lease x WHERE x.id=NEW.source_id;IF source_status<>'verified'OR NEW.date_semantics<>'lease_inclusive_end'OR NEW.source_key IS DISTINCT FROM basis_key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 租约提醒须有原房源的独立已核日期记录';END IF;END IF;
   IF g IS DISTINCT FROM NEW.group_id OR co IS DISTINCT FROM NEW.company_id OR person IS DISTINCT FROM NEW.subject_person_id OR due IS DISTINCT FROM NEW.due_on OR rev IS DISTINCT FROM NEW.source_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 到期提醒不得跨公司换原业务或伪造日期版本';END IF;
   SELECT CASE WHEN b.account_id IS NOT NULL THEN b.group_id ELSE f.group_id END,CASE WHEN b.account_id IS NOT NULL THEN b.person_id ELSE f.person_id END INTO actor_group,actor_person FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile f ON f.account_id=a.id WHERE a.id=NEW.recipient_account_id AND a.status='active';IF actor_group IS DISTINCT FROM NEW.group_id OR actor_person IS DISTINCT FROM NEW.recipient_person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 原生提醒须明确当前收件人员及账号';END IF;
  ELSE IF(to_jsonb(NEW)-ARRAY['state','reason_code','closed_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','reason_code','closed_at'])OR OLD.state<>'open'AND NEW.state IS DISTINCT FROM OLD.state THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 原生提醒来源及已结束记录不可换绑或复活';END IF;END IF;
 ELSIF TG_TABLE_NAME='ty_br_delivery'THEN
  SELECT*INTO r FROM public.ty_br_rule WHERE id=NEW.rule_id;SELECT*INTO n FROM public.ty_br_notice WHERE id=NEW.notice_id;
  IF ROW(NEW.group_id,NEW.company_id,NEW.rule_code,NEW.connection_id,NEW.profile_id,NEW.source_key,NEW.source_hash,NEW.due_on,NEW.recipient_account_id,NEW.recipient_person_id)IS DISTINCT FROM ROW(r.group_id,n.company_id,r.code,r.connection_id,r.profile_id,n.source_key,n.source_hash,n.due_on,n.recipient_account_id,n.recipient_person_id)OR n.group_id<>r.group_id OR NOT n.kind=ANY(r.reminder_types)OR r.company_id IS NOT NULL AND NOT public.fn_ty_ix_company_contains(r.company_id,n.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 日期投递须对应同一规则、原提醒及永久收件人';END IF;
  IF TG_OP='INSERT'AND(r.status<>'approved'OR EXISTS(SELECT 1 FROM public.ty_nx_delivery x WHERE x.public_key=NEW.public_key))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 投递须有真实已核规则且事项引用不能冒认审批';END IF;
  IF NEW.identity_id IS NOT NULL THEN SELECT*INTO m FROM public.ty_ix_identity WHERE id=NEW.identity_id;IF m.connection_id<>r.connection_id OR m.external_kind<>'person'OR m.person_id<>NEW.recipient_person_id OR m.external_id<>NEW.recipient_external_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 平台映射须精确对应到期提醒收件人';END IF;END IF;
  IF NEW.job_id IS NOT NULL THEN SELECT*INTO j FROM public.ty_ix_job WHERE id=NEW.job_id;IF j.connection_id<>r.connection_id OR j.profile_id<>r.profile_id OR j.created_by<>r.approved_by OR j.kind<>'message.send'OR j.request->>'source_kind'<>'business_reminder_delivery'OR j.request->>'source_id'<>NEW.id::text OR(j.request->>'recipient_account_id')::bigint<>NEW.recipient_account_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 到期提醒必须关联其真实225发送任务和已授权HR';END IF;END IF;
  IF NEW.transport_receipt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_ix_delivery_receipt z WHERE z.id=NEW.transport_receipt_id AND z.job_id=NEW.job_id AND z.connection_id=NEW.connection_id AND z.outcome='confirmed'AND z.remote_id=NEW.remote_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 受理状态须有225真实平台响应';END IF;
  mutable:=ARRAY['identity_id','identity_revision','recipient_external_id','job_id','transport_receipt_id','state','acceptance_state','delivery_state','read_state','platform_result','remote_id','reported_read_at','observed_read_at','last_polled_at','error_code','revision'];
  IF TG_OP='UPDATE'AND((to_jsonb(NEW)-mutable)IS DISTINCT FROM(to_jsonb(OLD)-mutable)OR OLD.job_id IS NOT NULL AND ROW(NEW.job_id,NEW.identity_id,NEW.identity_revision,NEW.recipient_external_id)IS DISTINCT FROM ROW(OLD.job_id,OLD.identity_id,OLD.identity_revision,OLD.recipient_external_id)OR OLD.transport_receipt_id IS NOT NULL AND ROW(NEW.transport_receipt_id,NEW.remote_id)IS DISTINCT FROM ROW(OLD.transport_receipt_id,OLD.remote_id)OR OLD.acceptance_state='provider_accepted'AND NEW.acceptance_state<>OLD.acceptance_state OR OLD.read_state='provider_reported_read'AND NEW.read_state<>OLD.read_state OR OLD.delivery_state='implied_by_read'AND NEW.delivery_state<>OLD.delivery_state OR OLD.observed_read_at IS NOT NULL AND NEW.observed_read_at IS DISTINCT FROM OLD.observed_read_at OR OLD.reported_read_at IS NOT NULL AND(NEW.reported_read_at IS NULL OR NEW.reported_read_at<OLD.reported_read_at))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 原投递、真实受理与已读事实不可换绑或倒退';END IF;
 ELSIF TG_TABLE_NAME='ty_br_receipt_job'THEN
  SELECT*INTO d FROM public.ty_br_delivery WHERE id=NEW.delivery_id;IF d.remote_id IS NULL OR d.acceptance_state<>'provider_accepted'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 回读须有实际已受理消息';END IF;
  IF TG_OP='INSERT'AND NEW.state<>'queued'OR TG_OP='UPDATE'AND((to_jsonb(NEW)-ARRAY['state','lease_token','lease_until','attempts','error_code','result','revision','completed_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','lease_token','lease_until','attempts','error_code','result','revision','completed_at'])OR NEW.revision<>OLD.revision+1 OR OLD.state NOT IN('queued','leased')OR OLD.state='queued'AND NEW.state NOT IN('leased','blocked')OR OLD.state='leased'AND NEW.state NOT IN('leased','completed','failed','blocked'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 回执查询来源、请求人和租约不可换绑';END IF;
 ELSIF TG_TABLE_NAME='ty_br_observation'THEN
  IF TG_OP='UPDATE'AND((to_jsonb(NEW)-ARRAY['delivery_id','state','error_code','applied_at','last_checked_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['delivery_id','state','error_code','applied_at','last_checked_at'])OR OLD.delivery_id IS NOT NULL AND NEW.delivery_id IS DISTINCT FROM OLD.delivery_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 日期回执原文及确切关联不可改写';END IF;
  SELECT*INTO c FROM public.ty_integration_connection WHERE id=NEW.connection_id;IF c.provider<>NEW.provider OR NEW.envelope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_ix_callback_envelope x WHERE x.id=NEW.envelope_id AND x.connection_id=c.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 回执须引用同平台已验签原件';END IF;
  IF NEW.receipt_job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_br_receipt_job x JOIN public.ty_br_delivery z ON z.id=x.delivery_id WHERE x.id=NEW.receipt_job_id AND x.state='leased'AND z.connection_id=c.id AND z.remote_id=NEW.remote_id AND z.recipient_external_id=NEW.recipient_external_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 主动回读须引用此消息真实查询租约';END IF;
  IF NEW.delivery_id IS NOT NULL THEN SELECT*INTO d FROM public.ty_br_delivery WHERE id=NEW.delivery_id;IF d.connection_id<>c.id OR d.remote_id IS DISTINCT FROM NEW.remote_id OR d.recipient_external_id IS DISTINCT FROM NEW.recipient_external_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 回执不能冒认其他消息和人员';END IF;END IF;
 END IF;RETURN NEW;END$$;
CREATE TRIGGER ty_br_lease_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_br_lease FOR EACH ROW EXECUTE FUNCTION fn_ty_br_guard();
CREATE TRIGGER ty_br_rule_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_br_rule FOR EACH ROW EXECUTE FUNCTION fn_ty_br_guard();
CREATE TRIGGER ty_br_notice_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_br_notice FOR EACH ROW EXECUTE FUNCTION fn_ty_br_guard();
CREATE TRIGGER ty_br_delivery_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_br_delivery FOR EACH ROW EXECUTE FUNCTION fn_ty_br_guard();
CREATE TRIGGER ty_br_receipt_job_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_br_receipt_job FOR EACH ROW EXECUTE FUNCTION fn_ty_br_guard();
CREATE TRIGGER ty_br_observation_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_br_observation FOR EACH ROW EXECUTE FUNCTION fn_ty_br_guard();
CREATE FUNCTION fn_ty_br_receipt_proof()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE d public.ty_br_delivery%ROWTYPE;
BEGIN SELECT*INTO d FROM public.ty_br_delivery WHERE id=NEW.id;
 IF d.acceptance_state='provider_accepted'AND NOT EXISTS(SELECT 1 FROM public.ty_ix_delivery_receipt z WHERE z.id=d.transport_receipt_id AND z.job_id=d.job_id AND z.outcome='confirmed'AND z.remote_id=d.remote_id)OR d.read_state='provider_reported_read'AND NOT EXISTS(SELECT 1 FROM public.ty_br_observation o WHERE o.delivery_id=d.id AND o.state='applied'AND o.kind='read'AND o.remote_id=d.remote_id AND o.recipient_external_id=d.recipient_external_id)OR d.read_state='provider_reported_unread'AND NOT EXISTS(SELECT 1 FROM public.ty_br_observation o WHERE o.delivery_id=d.id AND o.state='applied'AND o.kind='unread')OR d.delivery_state='implied_by_read'AND d.read_state<>'provider_reported_read'OR d.reported_read_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_br_observation o WHERE o.delivery_id=d.id AND o.state='applied'AND o.kind='read'AND o.reported_at=d.reported_read_at)OR d.observed_read_at IS NOT NULL AND d.read_state<>'provider_reported_read'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 平台受理、送达和阅读须有确切真实响应或已验回执';END IF;RETURN NEW;END$$;
CREATE CONSTRAINT TRIGGER ty_br_receipt_proof AFTER INSERT OR UPDATE ON ty_br_delivery DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_br_receipt_proof();
CREATE INDEX ty_br_rule_scan ON ty_br_rule(status,last_scanned_at,id);
CREATE INDEX ty_br_notice_recipient ON ty_br_notice(group_id,recipient_account_id,state,id);
CREATE INDEX ty_br_pending_receipts ON ty_br_observation(state,last_checked_at,id);

-- Extend the existing native inbox domain only; message receipts remain separate.
ALTER TABLE ty_portal_read DROP CONSTRAINT ty_portal_read_domain_check;
ALTER TABLE ty_portal_read ADD CONSTRAINT ty_portal_read_domain_check CHECK(domain IN('workflow_copy','performance_notice','contract_reminder','certificate_reminder','learning_notice','business_reminder'));
CREATE FUNCTION fn_ty_br_portal_read_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN IF NEW.domain='business_reminder'AND NOT EXISTS(SELECT 1 FROM public.ty_br_notice n WHERE n.id::text=NEW.source_id AND n.group_id=NEW.group_id AND n.recipient_account_id=NEW.account_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='到期提醒已读须为确切本人站内来源';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_br_portal_read_guard BEFORE INSERT ON ty_portal_read FOR EACH ROW EXECUTE FUNCTION fn_ty_br_portal_read_guard();
